--region init
function StoreGift:InitHandler()
    self._onRefreshStoreEvent = Events.AddListener(StoreConstants.StoreEvents.OnRefreshStore, Bind(self, self.OnRefreshStoreEventHandler))
    
    self._tickHandler = Bind(self, self.OnTimeTick)
    StoreShared:RegisterTimer(self._tickHandler)
end

function StoreGift:InitData()
    local comp = StoreUtils.GetStoreComp()
