end

---定时器处理
function StoreGift:OnTimeTick()
    local refresh = false
    for _, v in pairs(checkTable(self._storeData)) do
        for _, giftData in pairs(checkTable(v)) do
            if giftData.nextRefreshLeftSeconds == 0 then
                refresh = true
                break;
            end
        end
        if refresh then
            break
        end
    end

    if refresh then
        GameUtils.Request(Interfaces.StoreHome, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                StoreUtils.RefreshStore(response.data)
            end
        end)
        return
    end
end
--endregion handler

