    if params.itemData then
        self.co = cs_coroutine.start(function()
            CfUtils.PlayAnimator(self.Root, "Default")
            StoreUtils.OpenChestBuyDialog(StoreConstants.OpenIds.Gift, params.itemData)
        end)
    end
end
