--region private
---转换礼包商城数据
function StoreGift:ConvertStoreData(data)
    local storeData = {}
    for _, v in ipairs(checkTable(data)) do
        if storeData[tostring(v.tab)] then
            table.insert(storeData[tostring(v.tab)], v)
        else
            storeData[tostring(v.tab)] = {v}
        end
    end
    self._storeData = storeData
end

---排序
function StoreGift:SortStoreData()
    for _, v in pairs(self._storeData) do
        table.sort(v, function(a, b)
            local isFreeA = StoreUtils.ProductIsFree(a)
            local isFreeB = StoreUtils.ProductIsFree(b)
            local isSoldOutA = StoreUtils.ProductIsSoldOut(a)
            local isSoldOutB = StoreUtils.ProductIsSoldOut(b)
            if isFreeA ~= isFreeB then
                return isFreeA
            elseif isSoldOutA ~= isSoldOutB then
                return not isSoldOutA
            elseif a.activityUuid ~= b.activityUuid then
                return a.activityUuid > b.activityUuid
            elseif a.pos ~= b.pos then
                return a.pos < b.pos
            else
                return a.productId < b.productId
            end
        end)
    end
end

---刷新列表
function StoreGift:RefreshList()
    KTool.DestroyGameObjectChildren(self.Content.gameObject)
    for i, v in ipairs(TabOrder) do
        if self._storeData[tostring(v)] then
            self:InstantiateLayoutNode(v)
        end
    end
    
end

---实例化LayoutNode
---@param giftType integer 礼包类型
function StoreGift:InstantiateLayoutNode(giftType)
    local layout = CfUtils.InstantiateGo(self.GridLayoutNode.gameObject, self.Content.gameObject)
    CfUtils.SetActive(layout, true)
    
    -- 标题
    local titleNode = layout.transform:Find('TitleNode')
    local imgLine = titleNode.transform:Find('ImgLine')
    local textTitle = titleNode.transform:Find('TextTitle')
    local textTime = titleNode.transform:Find('TextTime')
    if giftType == StoreConstants.StoreGiftType.Activity then
        CfUtils.FillText(textTitle, localize("活动特惠"))
        CfUtils.SetActive(textTime, false)
        CfUtils.SetUISwitchImage(imgLine, 2)
    elseif giftType == StoreConstants.StoreGiftType.Daily then
        CfUtils.FillText(textTitle, localize("每日特惠"))
        CfUtils.SetActive(textTime, true)
        CfUtils.FillText(textTime, localize("每日5:00重置"))
        CfUtils.SetUISwitchImage(imgLine, 1)
    elseif giftType == StoreConstants.StoreGiftType.Weekly then
        CfUtils.FillText(textTitle, localize("每周特惠"))
        CfUtils.SetActive(textTime, true)
        CfUtils.FillText(textTime, localize("周一5:00重置"))
        CfUtils.SetUISwitchImage(imgLine, 1)
    elseif giftType == StoreConstants.StoreGiftType.Monthly then
        CfUtils.FillText(textTitle, localize("每月特惠"))
        CfUtils.SetActive(textTime, true)
        CfUtils.FillText(textTime, localize("月初5:00重置"))
        CfUtils.SetUISwitchImage(imgLine, 1)
    end

    -- 实例化礼包
    local cell = layout.transform:Find('Cell')
    local giftNum = table.count(self._storeData[tostring(giftType)])
    for i = 1, math.ceil(giftNum / 2) * 2 do
        local cellGo = CfUtils.InstantiateGo(cell, layout)
        CfUtils.SetActive(cellGo, true)
        local chestCellScr = CfUtils.GetLuaScr(cellGo, GiftCellPath)
        if chestCellScr then
            if self._storeData[tostring(giftType)][i] then
                chestCellScr:RefreshCell(StoreConstants.OpenIds.Gift, self._storeData[tostring(giftType)][i])
            else
                chestCellScr:EmptyState()
            end
        end
    end
end
--endregion private

return StoreGift